```ts button/button.component.ts
import { CommonModule } from '@angular/common';
import {
  ChangeDetectorRef,
  Component,
  EventEmitter,
  Input,
  ViewEncapsulation,
} from '@angular/core';
import { BaseComponent, componentName } from '../../../core/base/base.component';
import { IconComponent } from '../icon/icon.component';

const BUTTON_CLASSES = {
  primary: 'button-primary',
  secondary: 'button-secondary',
  secondaryInverse: 'button-secondary-inverse',
  tertiary: 'button-tertiary',
  background: 'button-background',
  ghost: 'button-ghost',
};

const BUTTON_SIZES = {
  small: 'button-small',
  puffy: 'button-puffy',
  default: 'button',
};

@Component({
  selector: `${componentName}-button`,
  templateUrl: './button.component.html',
  styleUrls: ['./button.component.scss'],
  standalone: true,
  encapsulation: ViewEncapsulation.ShadowDom,
  imports: [CommonModule, IconComponent],
})

export class ButtonComponent extends BaseComponent {

  @Input() typeButton: 'primary' | 'secondary' | 'secondaryInverse' | 'tertiary' | 'background' | 'ghost' = 'primary';
  @Input() iconName = '';
  @Input() sizeButton: 'default' | 'small' | 'puffy' = 'default';
  @Input() class = '';
  @Input() icon = '';
  @Input() id = '';
  @Input() disabled = false;
  @Input() iconPosition: 'left' | 'right' = 'right';
  @Input() width: 'fill' | 'hug' = 'fill';
  @Input('aria-label') ariaLabel = '';
  @Input('aria-describedby') ariaDescribedby = '';

  buttonClick = new EventEmitter<void>();

  constructor(changeDetectorRef: ChangeDetectorRef) {
    super(changeDetectorRef);
  }


  setClasses(): string[] {
    return [
      this.class,
      this.setButtonType(),
      this.setSize(),
      this.setDynamicSizeClass(),
      this.setIconPosition(),
    ].filter((className) => className !== '');
  }

  private setButtonType(): string {
    return BUTTON_CLASSES[this.typeButton];
  }

  private setSize(): string {
    return BUTTON_SIZES[this.sizeButton];
  }

  private setDynamicSizeClass(): string {
    return this.width === 'fill' ? '' : 'button-hug';
  }

  private setIconPosition(): string {
    return this.iconPosition === 'left' ? 'button-icon-left' : '';
  }

  onClick(): void {
    this.buttonClick.emit();
  }
}
